import{d as g,C as n,o as s,c as h,E as t,a3 as a}from"./chunks/framework.D4-ViStF.js";const b=JSON.parse('{"title":"否卦","description":"第十二卦·天地否——天地不交，俭德辟难。","frontmatter":{"title":"否卦","description":"第十二卦·天地否——天地不交，俭德辟难。","category":"hexagram","aliases":["否","天地否"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-12.md","filePath":"yijing/hexagrams/hexagram-12.md","lastUpdated":1787730063000}'),p={name:"yijing/hexagrams/hexagram-12.md"},x=g({...p,setup(m){const o=[{id:"bamaoru",term:"拔茅茹",pinyin:"bá máo rú",meaning:"拔茅草，根系相连，拔一根带出一片。喻同类相连、牵一发而动全身。"},{id:"yiqihui",term:"以其汇",pinyin:"yǐ qí huì",meaning:"因为同类汇聚。汇，类聚。「以其汇」即因其同类相聚。"},{id:"baocheng",term:"包承",pinyin:"bāo chéng",meaning:"包容承受；承，顺承。「包承」：包容而顺承。"},{id:"piheng",term:"否亨",pinyin:"pǐ hēng",meaning:"否局中的亨通。大人否亨：在否局中内心通道未断。"},{id:"baoxiu",term:"包羞",pinyin:"bāo xiū",meaning:"包住羞耻，用惯性与成果掩盖违心。"},{id:"youming",term:"有命",pinyin:"yǒu mìng",meaning:"有天命、本然。不是外求的使命，是迷雾散去后本来就在那里的本然。"},{id:"choulizhi",term:"畴离祉",pinyin:"chóu lí zhǐ",meaning:"畴为同类，离为附丽，祉为福。认出自己的命后，同道之人自然聚拢，福祉随之而来。"},{id:"xiupi",term:"休否",pinyin:"xiū pǐ",meaning:"休止否运、终结否局。"},{id:"baosang",term:"苞桑",pinyin:"bāo sāng",meaning:"桑树丛生，根系极深。「系于苞桑」即系于根深之桑。"},{id:"qiwang",term:"其亡其亡",pinyin:"qí wáng qí wáng",meaning:"警惕「将要灭亡」，清醒的自我警示：越看见转机，越要提醒自己还没稳。"},{id:"qingpi",term:"倾否",pinyin:"qīng pǐ",meaning:"倾覆否局，否极泰来。"},{id:"buluanqun",term:"不乱群",pinyin:"bù luàn qún",meaning:"不乱于群。大人否亨，因不同流合污。"},{id:"weibudang",term:"位不当",pinyin:"wèi bù dàng",meaning:"位置不当。包羞，因位不当——用错的方式掩盖。"},{id:"zhixing",term:"志行",pinyin:"zhì xíng",meaning:"志向得以施行。有命无咎，因志行。"},{id:"weizhengdang",term:"位正当",pinyin:"wèi zhèng dàng",meaning:"位置正当。大人之吉，因位正当。"},{id:"hekchang",term:"何可长",pinyin:"hé kě cháng",meaning:"怎么能长久。否终则倾，何可长也。"}],e=[{position:"初六",type:"yin",text:"拔茅茹，以其汇，贞吉亨。",xiang:"拔茅贞吉，志在君也。",textModern:"茅草根系相连，拔一根带出一片——否局初起，周围人开始站队、结党；守住本心、不急于站队，守正才有亨通。",xiangModern:"拔茅而守正则吉，因为志向在正道，不在随波逐流。"},{position:"六二",type:"yin",text:"包承，小人吉，大人否亨。",xiang:"大人否亨，不乱群也。",textModern:"小人顺势而吉，是顺了否；大人在「小人外象」与「君子内志」的缝隙中保持通达——否局中的亨，是内心那个看不见的通道被点亮。",xiangModern:"大人的否亨，在于不乱于群——不同流合污，守住内心的通道。"},{position:"六三",type:"yin",text:"包羞。",xiang:"包羞，位不当也。",textModern:"包住了羞耻，用惯性与成果掩盖违心；包而不发，缝隙越来越深。停止掩盖、承认缝隙，才是重回通达的起点。",xiangModern:"包羞，是因为位置不当——用错的方式掩盖，越包越深。"},{position:"九四",type:"yang",text:"有命，无咎，畴离祉。",xiang:"有命无咎，志行也。",textModern:"从顺承转为刚健，是生命的觉醒时刻；「有命」不是外求的使命，是迷雾散去后本来就在那里的本然。认出自己的命后，同道之人自然聚拢，福祉随之而来。",xiangModern:"有命而无咎，是因为志向得以施行——把「我」和「道」厘清，不再需要「正确」来确认自身。"},{position:"九五",type:"yang",text:"休否，大人吉。其亡其亡，系于苞桑。",xiang:"大人之吉，位正当也。",textModern:"转折点已至，但危险未除；越是看见转机，越要清醒自警「还没稳」。根系要深扎——根不在有志的样子里，在不管今天表现如何都还在的那个本然的兑里。",xiangModern:"大人的吉，在于位置正当——居最高位而能休否，正是守正的结果。"},{position:"上九",type:"yang",text:"倾否，先否后喜。",xiang:"否终则倾，何可长也。",textModern:"否局被彻底倾覆，先经历否，后迎来喜。倾否是道的动作，后喜是君子配得上那个喜——否极泰来，不是等来的，是守来的。",xiangModern:"否到了尽头就会倾覆，这样的否局怎么能长久呢。"}];return(u,i)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return s(),h("div",null,[t(r,{name:"否",fullName:"天地否",upper:"☰",lower:"☷",guaCi:"否之匪人，不利君子贞，大往小来。",pinyin:["pǐ"],element:"金",direction:"西北",insight:"天地不交，万物不通；否极泰来，君子守通道以待倾否。",guaSlug:"12tiandipi",lines:e}),i[0]||(i[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>天地不交，否。君子以俭德辟难，不可荣以禄。</p><p>上乾为天、下坤为地，天在上、地在下，两不相交，正是闭塞之象。君子由此悟到：要<strong>收敛德性、俭约其才以避祸难</strong>，不可贪图荣耀与俸禄——否闭之世，越外显、越求荣禄，越容易招祸。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>否之匪人，不利君子贞，大往小来。则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子。小人道长，君子道消也。</p><p>逐句释义：</p><ul><li><strong>否之匪人，不利君子贞，大往小来</strong> —— 闭塞不合人道，不利于君子守正；阳气（大）消往，阴气（小）来长。</li><li><strong>则是天地不交而万物不通也</strong> —— 这是因为天地不相交，万物不得相通。</li><li><strong>上下不交而天下无邦也</strong> —— 上下不交，天下就不成其为邦国。</li><li><strong>内阴而外阳，内柔而外刚，内小人而外君子</strong> —— 内里阴柔小人、外表阳刚君子，表里相悖。</li><li><strong>小人道长，君子道消也</strong> —— 小人之道增长，君子之道消退。</li></ul><blockquote><p><strong>否局之辨</strong>：小人之道外求、顺势而为、顺否而长；君子之道内守、守正不移、守住通道。小人得势于一时，君子配得上倾否后的喜。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),t(l,{element:"金",guaSlug:"12tiandipi",glossary:o,items:e}),i[1]||(i[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-拔茅茹-以其汇-贞吉亨" tabindex="-1">初六 · 拔茅茹，以其汇，贞吉亨 <a class="header-anchor" href="#初六-·-拔茅茹-以其汇-贞吉亨" aria-label="Permalink to &quot;初六 · 拔茅茹，以其汇，贞吉亨&quot;">​</a></h3><ul><li>象意：茅草根系相连，拔一根带出一片</li><li>处境：否局初起，势头刚成，周围人开始站队、结党</li><li><strong>智慧</strong>：守住本心，不急于站队；守正，才有亨通</li></ul><blockquote><p>否局初起时，最难的不是对抗，是不随波逐流。根还浅，先守住。</p></blockquote><h3 id="六二-·-包承-小人吉-大人否亨" tabindex="-1">六二 · 包承，小人吉，大人否亨 <a class="header-anchor" href="#六二-·-包承-小人吉-大人否亨" aria-label="Permalink to &quot;六二 · 包承，小人吉，大人否亨&quot;">​</a></h3><ul><li>象意：包，包容承受；承，顺承</li><li>处境：否局引力最强处，小人得势，大人处境艰难</li><li>小人顺势而吉，是顺了否；大人在「小人外象」与「君子内志」的缝隙中保持通达</li><li><strong>否亨</strong>：否局中的亨，是内心那个看不见的通道被点亮</li></ul><blockquote><p>真正的亨不是外部的顺遂，而是内心通道未断。德在，通道就在。</p></blockquote><h3 id="六三-·-包羞" tabindex="-1">六三 · 包羞 <a class="header-anchor" href="#六三-·-包羞" aria-label="Permalink to &quot;六三 · 包羞&quot;">​</a></h3><ul><li>象意：包住了羞耻</li><li>处境：坤道极处，用惯性掩盖违心，假性重回正轨</li><li><strong>危险</strong>：用「一贯的习惯」去掩盖内心的羞耻；用成果（笔记、赞赏）填补内心空虚；包而不发，缝隙越来越深</li><li><strong>转化关键</strong>：停止掩盖，承认缝隙；不需要观众也能安住的时刻，才是贞</li></ul><blockquote><p>包羞不是恶，是还没看清包住的是什么。承认缝隙，才是重回通达的起点。</p></blockquote><h3 id="九四-·-有命-无咎-畴离祉" tabindex="-1">九四 · 有命，无咎，畴离祉 <a class="header-anchor" href="#九四-·-有命-无咎-畴离祉" aria-label="Permalink to &quot;九四 · 有命，无咎，畴离祉&quot;">​</a></h3><ul><li>象意：从内卦（坤）进入外卦（乾），从顺承转为刚健</li><li>处境：否卦的转折点，生命的觉醒时刻</li><li><strong>「有命」的真义</strong>：不是外求的使命，是迷雾散去后本来就在那里的「本然」；发现了道，但不是创造了道</li><li><strong>厘清</strong>：道是道，我是我——不是切断，是厘清；不再需要「正确」这一标准来确认自身存在</li><li><strong>畴离祉</strong>：认出自己的命后，同道之人自然聚拢，福祉随之而来</li></ul><blockquote><p>苦苦追寻的从来不在远处，而是颤动之后，遮蔽散去，本来就在那里的自己。</p></blockquote><h3 id="九五-·-休否-大人吉。其亡其亡-系于苞桑" tabindex="-1">九五 · 休否，大人吉。其亡其亡，系于苞桑 <a class="header-anchor" href="#九五-·-休否-大人吉。其亡其亡-系于苞桑" aria-label="Permalink to &quot;九五 · 休否，大人吉。其亡其亡，系于苞桑&quot;">​</a></h3><ul><li>象意：休否，终结否局；苞桑，桑树丛生，根系极深</li><li>处境：否卦最高位的君子，转折点已至，但危险未除</li><li><strong>「其亡其亡」的真义</strong>：不是庆幸，不是担忧，是清醒的自我警示——越是看见转机，越要提醒自己还没稳</li><li><strong>根在哪里</strong>：根不在「有志的样子」里（早起、练习、自律），在不管今天表现如何都还在的那个本然的兑里</li></ul><blockquote><p>转机来了，正是需要扎根的时候。根不在有志的样子里，在那个本然的兑里。</p></blockquote><h3 id="上九-·-倾否-先否后喜" tabindex="-1">上九 · 倾否，先否后喜 <a class="header-anchor" href="#上九-·-倾否-先否后喜" aria-label="Permalink to &quot;上九 · 倾否，先否后喜&quot;">​</a></h3><ul><li>象意：倾，倾覆；否局被彻底倾覆，先经历否，后迎来喜</li><li><strong>倾否怎么发生</strong>：道自己倾的，天地有自然而然，否极必泰来</li><li><strong>但君子不是旁观者</strong>：倾否是道的动作，后喜是君子配得上那个喜；君子在否局里做了最难的事——没有变成否局本身</li><li><strong>先否后喜</strong>：否极泰来，不是等来的，是守来的</li></ul><blockquote><p>倾否是道的动作，后喜是君子配得上那个喜。否极泰来，不是等来的，是守来的。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',20)),t(d,{title:"字词释义",items:[{term:"否",pinyin:["pǐ"],meaning:"闭塞不通。天地不交，万物不通。"},{term:"拔茅茹",pinyin:["bá","máo","rú"],meaning:"拔茅草，根系相连，拔一根带出一片。"},{term:"以其汇",pinyin:["yǐ","qí","huì"],meaning:"因为同类汇聚。汇，类聚。"},{term:"包承",pinyin:["bāo","chéng"],meaning:"包容承受、顺承。"},{term:"包羞",pinyin:["bāo","xiū"],meaning:"包住羞耻，用惯性掩盖违心。"},{term:"有命",pinyin:["yǒu","mìng"],meaning:"有天命、本然。迷雾散去后本来就在那里的。"},{term:"畴离祉",pinyin:["chóu","lí","zhǐ"],meaning:"同类附丽而得福，同道聚拢、福祉随之而来。"},{term:"休否",pinyin:["xiū","pǐ"],meaning:"休止否运、终结否局。"},{term:"苞桑",pinyin:["bāo","sāng"],meaning:"桑树丛生，根系极深。"},{term:"倾否",pinyin:["qīng","pǐ"],meaning:"倾覆否局，否极泰来。"},{term:"俭德辟难",pinyin:["jiǎn","dé","bì","nàn"],meaning:"收敛德性以避祸难。象传的核心。"},{term:"匪人",pinyin:["fěi","rén"],meaning:"非人。「否之匪人」：闭塞不合人道、不是正道。"}]}),i[2]||(i[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>否卦讲的是<strong>闭塞与倾否</strong>。上乾（天）下坤（地），天在上、地在下，天地不交，万物不通。</p><p>卦辞「否之匪人，不利君子贞，大往小来」点明：闭塞之世不合人道，不利于君子守正；阳气（大）消往，阴气（小）来长。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>否局不仅是时势闭塞，更是共同体的瓦解——天地之间长出了「面子、阶层、焦虑」的墙。但那个「无」的通道从未断过，德在，通道就在。</p><p>小人之道顺势而为、顺否而长，得势于一时；君子之道守正不移、守住通道，配得上倾否后的喜。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>守住本心，不随波逐流（初六拔茅茹）</li><li>内心通道不断，德在通道就在（六二否亨）</li><li>承认缝隙，不掩盖（六三包羞）</li><li>厘清「道是道，我是我」（九四有命）</li><li>转机来时，更要扎根（九五其亡其亡）</li><li>守住等待泰来的通道（上九倾否）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>整体脉络：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>状态</th><th>功课</th></tr></thead><tbody><tr><td>初六</td><td>拔茅茹，以其汇，贞吉亨</td><td>蛰伏、守根</td><td>不随波逐流</td></tr><tr><td>六二</td><td>包承，小人吉，大人否亨</td><td>包承、守正</td><td>内心通道不断</td></tr><tr><td>六三</td><td>包羞</td><td>看见、承认</td><td>承认缝隙</td></tr><tr><td>九四</td><td>有命，无咎，畴离祉</td><td>厘清、有命</td><td>认出自己的命</td></tr><tr><td>九五</td><td>休否，其亡其亡，系于苞桑</td><td>扎根、苞桑</td><td>转机时更扎根</td></tr><tr><td>上九</td><td>倾否，先否后喜</td><td>倾否、后喜</td><td>守住等泰来</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>关于否局</strong>——否局是共同体的瓦解；那个「无」的通道从未断过，德在，通道就在</li><li><strong>关于包羞</strong>——包羞不是恶，是还没看清包住的是什么；承认缝隙，才是重回通达的起点</li><li><strong>关于有命</strong>——发现了道，但不是创造了道；苦苦追寻的从来不在远处</li><li><strong>关于苞桑</strong>——越觉得快赢了，越要其亡其亡；根不在有志的样子里，在兑里</li><li><strong>关于倾否</strong>——倾否是道的动作，后喜是君子配得上那个喜；否极泰来不是等来的，是守来的</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>从「包羞」到「有命」：</p><ul><li>曾经试图用「努力学习」掩盖内心的愧疚与不安——这是包而不发</li><li>意识到「成果的欣喜」向外，「道在心里的欣喜」向内，后者才是贞的体现</li><li>认出了命：对传统文化、经典典籍的本然信任，探究之后的那种兑</li></ul><p><strong>关于根在哪里</strong>：根在那个兑里——对经典的本然信任，探究之后的欣喜。早起、练习是枝叶，不是根。枝叶可以慢慢长，根不会因枝叶未长齐而消失。</p><p><strong>关于学习方式</strong>：喂到嘴边的是入口，从里面长出来的才是自己的。知识得来太易，怠惰与轻蔑是现代人的否局；其亡其亡，不只是警示外部的否，也是警示内部的松。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：泰（第十一卦）、同人（第十三卦）</li><li>否与泰：否极泰来——天地不交则否，天地交则泰</li><li>否与同人：否极，故受之以同人（《序卦传》）——否局散了，天地重新交通，第一件事是找到同道之人</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{b as __pageData,x as default};
